import sys

def is_regular_bracket_sequence(s):
    balance = 0
    question_marks = 0

    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        elif char == '?':
            question_marks += 1

        # If balance goes negative, it means there are more ')' than '('
        if balance < 0:
            return False

    # After processing all characters, balance should be zero
    # and we should have enough question marks to balance it out
    return balance == 0 and question_marks >= abs(balance)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1

    results = []

    for _ in range(t):
        s = data[index]
        index += 1
        if is_regular_bracket_sequence(s):
            results.append("YES")
        else:
            results.append("NO")

